CY.i18n.register("es", {"nanny.mood": "Su ánimo ahora: {n} %. Mejor ánimo, ayuda algo más eficaz. Baja despacio mientras trabaja y se recupera al salir.", "nanny.tip": "Dar un extra {n}", "nanny.tip_done": "Ya se dio hoy", "nanny.tip_wait": "Solo mientras está de servicio", "log.nanny_tip": "La niñera aceptó el extra, dio las gracias sonriendo y trabajó con más ganas."});
CY.i18n.register("es", {"shop.open": "Tienda", "shop.title": "Tienda", "shop.note": "Lo que compras se queda. Sin límite de tiempo ni descuentos, y el juego está completo sin comprar nada.", "shop.owned": "Tienes", "shop.locked": "Compra antes el nivel anterior", "shop.toy": "Juguete", "shop.toy_fx": "Bebés y niños pequeños necesitan jugar un cuarto más despacio y aparece un osito en el salón.", "shop.bed": "Una cama mejor", "shop.bed_fx": "El descanso se recupera un 30 % más rápido al dormir.", "shop.stroller": "Cochecito", "shop.stroller_fx": "Bebés y niños pequeños disfrutan más las salidas.", "shop.wheelchair": "Silla de ruedas", "shop.wheelchair_fx": "Los mayores necesitan moverse un 30 % más despacio y aparece una silla de ruedas en su cuarto.", "shop.decor1": "Decoración, nivel 1", "shop.decor1_fx": "Una planta en el salón, objetivo de ánimo +0,02 para todos.", "shop.decor2": "Decoración, nivel 2", "shop.decor2_fx": "Una alfombra y una lámpara de pie, objetivo de ánimo otros +0,02.", "shop.decor3": "Decoración, nivel 3", "shop.decor3_fx": "Una radio y más plantas, objetivo de ánimo otros +0,02.", "shop.house2": "Casa más grande", "shop.house2_fx": "Mudarse a una casa más grande: una habitación más con tres camas.", "log.bought": "Compraste {item}."});
